<?php if(!$rows): ?><div class="empty"><span aria-hidden="true">◇</span><h3>No hay registros para mostrar</h3><p>Los movimientos aparecerán aquí cuando se registren.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><?php foreach(array_keys($rows[0]) as $col): ?><th scope="col"><?= e(ucfirst(str_replace('_',' ',$col))) ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $value): ?><td><?= e($value) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div><?php endif ?>
